INSERT INTO public.mail_template_translation (mail_template_id, language_id, sender_name, subject, description, content_html, content_plain, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0dbf671338fabe1bb5b751327', '\x2fbb5fe2e29a4d70aa5854ce7ce3e20b', '{{ salesChannel.translated.name }}', 'Order confirmation', '', '<div style="font-family:arial; font-size:12px;">

    {% set currencyIsoCode = order.currency.isoCode %}
