INSERT INTO public.mail_template_translation (mail_template_id, language_id, sender_name, subject, description, content_html, content_plain, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0dc3373988b214c8d34b4272a', '\x01a20cc092c173728e52542b2dab195e', '{{ salesChannel.translated.name }}', 'Password zurücksetzen - {{ salesChannel.translated.name }}', 'Anfrage zum Zurücksetzen des Passworts', '<div style="font-family:arial; font-size:12px;">
