INSERT INTO public.mail_template_translation (mail_template_id, language_id, sender_name, subject, description, content_html, content_plain, custom_fields, created_at, updated_at) VALUES ('\x01a20cc1087d723f95c513f1e49a1dfc', '\x01a20cc092c173728e52542b2dab195e', '{{ salesChannel.translated.name }}', 'Neues Dokument für Ihre Bestellung', NULL, '<div style="font-family:arial; font-size:12px;">
    <br/>
    <p>
        {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ '' '' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},<br/>
        <br/>
        der Lieferstatus für Ihre Bestellung bei {{ salesChannel.translated.name }} (Number: {{ order.orderNumber }}) vom {{ order.orderDateTime|format_datetime(''medium'', ''short'', locale=''de-DE'') }} hat sich geändert.<br/>
        <strong>Die Bestellung hat jetzt den Lieferstatus: {{ order.deliveries.first.stateMachineState.translated.name }}.</strong><br/>
        <br/>
        Den aktuellen Status Ihrer Bestellung können Sie auch jederzeit auf unserer Webseite im  Bereich "Mein Konto" - "Meine Bestellungen" abrufen: {{ rawUrl(''frontend.account.order.single.page'', { ''deepLinkCode'': order.deepLinkCode }, salesChannel.domains|first.url) }}
        </br>
        Bei einer Gastbestellung können Sie den Status über den Link mit Ihrer E-Mail-Adresse und der Postleitzahl der Rechnungsanschrift abrufen.
        <br><br>
        {% if a11yDocuments %}
            Folgend stellen wir barrierefreie Dokumente als HTML-Version zur Verfügung:<br><br>
            {% for a11y in a11yDocuments %}
                {% set documentLink = rawUrl(
                    ''frontend.account.order.single.document.a11y'',
                    {
                        documentId: a11y.documentId,
                        deepLinkCode: a11y.deepLinkCode,
                        fileType: a11y.fileExtension,
                    },
                    salesChannel.domains|first.url
                )%}

                - <a href="{{ documentLink }}" target="_blank">{{ documentLink }}</a> <br>
            {% endfor %}<br>

            Aus Datenschutzgründen ist für die HTML-Version ein Login erforderlich.<br><br>
            Im Falle einer Gastbestellung können Sie Ihre E-Mail-Adresse und die Postleitzahl der Rechnungsanschrift verwenden.<br>
        {% endif %}
    </p>
