INSERT INTO public.mail_template_translation (mail_template_id, language_id, sender_name, subject, description, content_html, content_plain, custom_fields, created_at, updated_at) VALUES ('\x01a20cc220f673bb97b41e00675501a4', '\x01a20cc092c173728e52542b2dab195e', '{{ salesChannel.translated.name }}', 'Ihre Dateien von {{ salesChannel.translated.name }} stehen bereit', 'Shopware Default Template', '<div style="font-family:arial; font-size:12px;">

    {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ '' '' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},<br>
    <br>
    Mit dieser E-Mail erhalten Sie die Dateien zu der Bestellung: {{ order.orderNumber }}.
    <br>
    <br>

    <table border="0" style="font-family:Arial, Helvetica, sans-serif; font-size:12px;">
        <tr>
            <td bgcolor="#F7F7F2" style="border-bottom:1px solid #cccccc;"><strong>Produkt-Nr.</strong></td>
            <td bgcolor="#F7F7F2" style="border-bottom:1px solid #cccccc;"><strong>Produkt</strong></td>
            <td bgcolor="#F7F7F2" style="border-bottom:1px solid #cccccc;"><strong>Downloads</strong></td>
        </tr>

        {% for lineItem in order.lineItems %}
            {% if lineItem.downloads is defined and lineItem.downloads|length %}
                {% block lineItem %}
                    <tr>
                        <td>{% if lineItem.payload.productNumber is defined %}{{ lineItem.payload.productNumber|u.wordwrap(80) }}{% endif %}</td>
                        <td>{{ lineItem.label|u.wordwrap(80) }}</td>
                        <td>
                            {% for download in lineItem.downloads %}
                                {% if download.accessGranted %}
                                    {% set downloadLink = rawUrl(''frontend.account.order.single.download'', {''orderId'': order.id, ''downloadId'': download.id, ''deepLinkCode'': order.deepLinkCode}, salesChannel.domains|first.url) %}
                                    <a href="{{ downloadLink }}" target="_blank">
                                        {{ download.media.fileName }}.{{ download.media.fileExtension }}
                                    </a><br>
                                {% endif %}
                            {% endfor %}
                        </td>
                    </tr>
                {% endblock %}
            {% endif %}
        {% endfor %}
    </table>

    <br>
</div>
', '{% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ '' '' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},

Mit dieser E-Mail erhalten Sie die Dateien zu der Bestellung: {{ order.orderNumber }}.

{% for lineItem in order.lineItems %}{% if lineItem.downloads is defined and lineItem.downloads|length %}
{{ lineItem.label|u.wordwrap(80) }} {% if lineItem.payload.productNumber is defined %}({{ lineItem.payload.productNumber|u.wordwrap(80) }}){% endif %}

-------------------------------------
{% for download in lineItem.downloads %}{% if download.accessGranted %}
{{ download.media.fileName }}.{{ download.media.fileExtension }} - {% set downloadLink = rawUrl(''frontend.account.order.single.download'', {''orderId'': order.id, ''downloadId'': download.id, ''deepLinkCode'': order.deepLinkCode}, salesChannel.domains|first.url) %}{{ downloadLink }}
{% endif %}{% endfor %}

{% endif %}{% endfor %}
', NULL, '2026-11-24 08:52:58.747', NULL);
