INSERT INTO public.mail_template_translation (mail_template_id, language_id, sender_name, subject, description, content_html, content_plain, custom_fields, created_at, updated_at) VALUES ('\x01a20cc29fc5733798ac4117e44c53bc', '\x01a20cc092c173728e52542b2dab195e', '{{ salesChannel.translated.name }}', 'Widerrufsantrag erhalten', 'Widerrufsantrag vom Kunden erhalten', '<div style="font-family: arial; font-size: 12px;">
