INSERT INTO public.mail_template_translation (mail_template_id, language_id, sender_name, subject, description, content_html, content_plain, custom_fields, created_at, updated_at) VALUES ('\x01a20cc2a3877298910ee7b6fdc817fd', '\x01a20cc092c173728e52542b2dab195e', '{{ salesChannel.translated.name }}', 'Zahlungsart geändert', 'Bestätigung der Änderung der Zahlungsmethode', '<div style="font-family:arial; font-size:12px;">
    <p>Hallo {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ '' '' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},</p>
    <p>wir bestätigen, dass die Zahlungsart für Ihre Bestellung erfolgreich geändert wurde.</p>
    <p>
        <strong>Bestellnummer:</strong> {{ order.orderNumber }}<br>
        <strong>Neue Zahlungsart:</strong> {{ order.transactions.last.paymentMethod.translated.name }}
    </p>
    <p>Ihre Bestellung wird nun mit der ausgewählten Zahlungsart weiter verarbeitet.</p>
    <p>Für Rückfragen stehen wir Ihnen jederzeit gerne zur Verfügung.</p>
</div>', 'Hallo {% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ '' '' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},

wir bestätigen, dass die Zahlungsart für Ihre Bestellung erfolgreich geändert wurde.

Bestellnummer: {{ order.orderNumber }}
Neue Zahlungsart: {{ order.transactions.last.paymentMethod.translated.name }}

Ihre Bestellung wird nun mit der ausgewählten Zahlungsart weiter verarbeitet.

Für Rückfragen stehen wir Ihnen jederzeit gerne zur Verfügung.', NULL, '2026-11-24 08:53:32.239', NULL);
INSERT INTO public.mail_template_translation (mail_template_id, language_id, sender_name, subject, description, content_html, content_plain, custom_fields, created_at, updated_at) VALUES ('\x01a20cc2a3877298910ee7b6fdc817fd', '\x2fbb5fe2e29a4d70aa5854ce7ce3e20b', '{{ salesChannel.translated.name }}', 'Payment method changed', 'Confirmation of payment method change', '<div style="font-family:arial; font-size:12px;">
    <p>{% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ '' '' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},</p>
    <p>We confirm that the payment method for your order has been successfully changed.</p>
    <p>
        <strong>Order number:</strong> {{ order.orderNumber }}<br>
        <strong>New payment method:</strong> {{ order.transactions.last.paymentMethod.translated.name }}
    </p>
    <p>Your order will now be processed using the selected payment method.</p>
    <p>If you have any questions, do not hesitate to contact us.</p>
</div>', '{% if order.orderCustomer.salutation %}{{ order.orderCustomer.salutation.translated.letterName ~ '' '' }}{% endif %}{{ order.orderCustomer.firstName }} {{ order.orderCustomer.lastName }},

We confirm that the payment method for your order has been successfully changed.

Order number: {{ order.orderNumber }}
New payment method: {{ order.transactions.last.paymentMethod.translated.name }}

Your order will now be processed using the selected payment method.

If you have any questions, do not hesitate to contact us.', NULL, '2026-11-24 08:53:32.205', NULL);
