INSERT INTO public.payment_method_translation (payment_method_id, language_id, name, distinguishable_name, description, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0ce77727098698bd2f66b263e', '\x01a20cc092c173728e52542b2dab195e', 'Lastschrift', NULL, 'Vorab autorisierte Zahlungsvereinbarung, Zahlungen werden direkt vom zu belastenden Konto abgebucht.', NULL, '2026-11-24 08:51:32.115', NULL);
INSERT INTO public.payment_method_translation (payment_method_id, language_id, name, distinguishable_name, description, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0ce77727098698bd2f66b263e', '\x2fbb5fe2e29a4d70aa5854ce7ce3e20b', 'Direct Debit', NULL, 'Pre-authorized payment, funds are withdrawn directly from the debited account.', NULL, '2026-11-24 08:51:32.102', NULL);
INSERT INTO public.payment_method_translation (payment_method_id, language_id, name, distinguishable_name, description, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0cea473a7a4f9aceab4cf58e9', '\x01a20cc092c173728e52542b2dab195e', 'Rechnung', NULL, 'Sie zahlen einfach und bequem auf Rechnung. Shopware bietet z.B. auch die Möglichkeit, Rechnungen automatisiert erst ab der 2. Bestellung für Kunden zur Verfügung zu stellen, um Zahlungsausfälle zu vermeiden.', NULL, '2026-11-24 08:51:32.187', NULL);
INSERT INTO public.payment_method_translation (payment_method_id, language_id, name, distinguishable_name, description, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0cea473a7a4f9aceab4cf58e9', '\x2fbb5fe2e29a4d70aa5854ce7ce3e20b', 'Invoice', NULL, 'Payment by invoice. Shopware provides automatic invoicing for all customers on orders after the first. This is to avoid defaults on payment.', NULL, '2026-11-24 08:51:32.181', NULL);
INSERT INTO public.payment_method_translation (payment_method_id, language_id, name, distinguishable_name, description, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0cef9718f8f7be4e9914f801e', '\x01a20cc092c173728e52542b2dab195e', 'Nachnahme', NULL, 'Zahlung bei Erhalt der Ware.', NULL, '2026-11-24 08:51:32.248', NULL);
INSERT INTO public.payment_method_translation (payment_method_id, language_id, name, distinguishable_name, description, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0cef9718f8f7be4e9914f801e', '\x2fbb5fe2e29a4d70aa5854ce7ce3e20b', 'Cash on delivery', NULL, 'Payment upon receipt of goods.', NULL, '2026-11-24 08:51:32.231', NULL);
INSERT INTO public.payment_method_translation (payment_method_id, language_id, name, distinguishable_name, description, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0cf2f733cb8095dcc66a2cdda', '\x01a20cc092c173728e52542b2dab195e', 'Vorkasse', NULL, 'Sie zahlen einfach vorab und erhalten die Ware bequem und günstig bei Zahlungseingang nach Hause geliefert.', NULL, '2026-11-24 08:51:32.318', NULL);
INSERT INTO public.payment_method_translation (payment_method_id, language_id, name, distinguishable_name, description, custom_fields, created_at, updated_at) VALUES ('\x01a20cc0cf2f733cb8095dcc66a2cdda', '\x2fbb5fe2e29a4d70aa5854ce7ce3e20b', 'Paid in advance', NULL, 'Pay in advance and get your order afterwards', NULL, '2026-11-24 08:51:32.306', NULL);


